describeMatrix("serve static range", (t, { it, expect }) => {
  const body = "abcdefghij".repeat(100);
  const lastModified = new Date(1_700_000_000_000).toUTCString();
  const meta: StaticAssetMeta = {
    type: "text/plain",
    etag: '"v2"',
    mtime: 1_700_000_000_123,
    size: body.length,
  };
  const getContents = vi.fn((_id: string): BodyInit | null | undefined => body);

  beforeEach(() => {
    getContents.mockClear();
    t.app.all("/range/**", (event) => serveStatic(event, { getContents, getMeta: () => meta }));
  });

  const serveAsset = (prefix: string, options: ServeStaticOptions) => {
    t.app.all(`${prefix}/**`, (event) => serveStatic(event, options));
  };

  // RF-01
  it("announces Accept-Ranges on a full GET", async () => {
    const res = await t.fetch("/range/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(body);
  });

  it("announces Accept-Ranges on a full HEAD", async () => {
    const res = await t.fetch("/range/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  it("does not announce Accept-Ranges on 404 or 405", async () => {
    serveAsset("/missing", { getContents, getMeta: () => undefined });

    const notFound = await t.fetch("/missing/file.txt");
    expect(notFound.status).toBe(404);
    expect(notFound.headers.get("accept-ranges")).toBeNull();

    const notAllowed = await t.fetch("/range/file.txt", { method: "POST" });
    expect(notAllowed.status).toBe(405);
    expect(notAllowed.headers.get("accept-ranges")).toBeNull();
  });

  it("keeps an accept-ranges value set in options.headers", async () => {
    serveAsset("/none", { getContents, getMeta: () => meta, headers: { "accept-ranges": "none" } });
    const res = await t.fetch("/none/file.txt");
    expect(res.headers.get("accept-ranges")).toBe("none");
  });

  // RF-11
  it("answers POST with Range as 405 without reading the asset", async () => {
    const res = await t.fetch("/range/file.txt", {
      method: "POST",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(405);
    expect(res.headers.get("allow")).toBe("GET, HEAD");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("falls through POST with Range when fallthrough is set", async () => {
    t.app.all("/fall/**", async (event) => {
      const res = await serveStatic(event, { getContents, getMeta: () => meta, fallthrough: true });
      return res ?? "next";
    });
    const res = await t.fetch("/fall/file.txt", {
      method: "POST",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("next");
  });

  // RF-02
  it("serves bytes=0-99 as 206 with the sliced body", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(body.slice(0, 100));
    expect(getContents).toHaveBeenCalledTimes(1);
  });

  // RF-03
  for (const [range, start, end] of [
    ["bytes=500-", 500, 999],
    ["bytes=0-", 0, 999],
    ["bytes=999-999", 999, 999],
    ["bytes=-100", 900, 999],
    ["bytes=-5000", 0, 999],
    ["bytes=990-5000", 990, 999],
  ] as const) {
    it(`serves ${range} as 206`, async () => {
      const res = await t.fetch("/range/file.txt", { headers: { range } });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe(`bytes ${start}-${end}/1000`);
      expect(res.headers.get("content-length")).toBe(String(end - start + 1));
      expect(await res.text()).toBe(body.slice(start, end + 1));
    });
  }

  // RF-04
  it("answers HEAD with Range using headers only", async () => {
    const res = await t.fetch("/range/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  // RF-05
  for (const range of [
    "items=0-1",
