  // RF-10
  for (const [name, assetMeta] of [
    ["no size", { type: "text/plain", etag: '"v2"' }],
    ["size 0", { type: "text/plain", etag: '"v2"', size: 0 }],
  ] as const) {
    it(`ignores Range for an asset with ${name}`, async () => {
      serveAsset("/unsized", { getContents, getMeta: () => assetMeta });
      const res = await t.fetch("/unsized/file.txt", { headers: { range: "bytes=0-99" } });
      expect(res.status).toBe(200);
