    ],
  ];
  for (const [kind, makeBody] of bodies) {
    it(`slices a ${kind} body for a 206`, async () => {
      serveAsset("/kind", { getContents: () => makeBody(), getMeta: () => meta });
      const res = await t.fetch("/kind/file.txt", { headers: { range: "bytes=100-199" } });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 100-199/1000");
      expect(await res.text()).toBe(body.slice(100, 200));
    });
  }

  // D-08
  it("answers 200 without Range when the body length differs from size", async () => {
    serveAsset("/short", { getContents: () => "x".repeat(900), getMeta: () => meta });
    const res = await t.fetch("/short/file.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toHaveLength(900);
  });

  // D-09
  it("answers 200 without Range when getContents returns null", async () => {
    serveAsset("/empty", { getContents: () => null, getMeta: () => meta });
    const res = await t.fetch("/empty/file.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("");
  });

  // D-11
  it("replaces a content-length set in options.headers on 206 and HEAD 206", async () => {
